===== lib/creator.ts =====
import { cache } from "react";
import type { Creator } from "@/lib/generated/prisma/client";
import { prisma } from "@/lib/prisma";

// The portal has exactly one creator and no auth, so every surface resolves it
// here on the server. Nothing takes a creator id from the client.
export const getCreator = cache(async (): Promise<Creator> => {
  const creator = await prisma.creator.findFirst({
    orderBy: { createdAt: "asc" },
  });

  if (!creator) {
    throw new Error(
      "No creator found. Run `npm run db:seed` to populate the portal.",
    );
  }

  return creator;
});

===== lib/prisma.ts =====
import { PrismaPg } from "@prisma/adapter-pg";
import { PrismaClient } from "@/lib/generated/prisma/client";

function connectionString(): string {
  const url = process.env.DATABASE_URL;
  if (!url) {
    throw new Error("DATABASE_URL is not set. Copy .env.example to .env.local.");
  }
  return url;
}

// Pooled connection: Prisma 7 talks to Postgres through a driver adapter, so
// the app gets Neon's pooler while the CLI keeps the direct URL for migrations.
function createPrismaClient() {
  return new PrismaClient({
    adapter: new PrismaPg({ connectionString: connectionString() }),
  });
}

const globalForPrisma = globalThis as unknown as {
  prisma?: ReturnType<typeof createPrismaClient>;
};

export const prisma = globalForPrisma.prisma ?? createPrismaClient();

// Without this, every dev hot reload would open another connection pool.
if (process.env.NODE_ENV !== "production") {
  globalForPrisma.prisma = prisma;
}

===== app/accounts/page.tsx =====
import type { Metadata } from "next";

export const metadata: Metadata = {
  title: "Accounts",
};

export default function AccountsPage() {
  return (
    <>
      <h1 className="text-xl font-semibold">Connected accounts</h1>
      <p className="mt-2 text-muted">
        Channel list, connection state, and connect and disconnect actions land
        here in feature 3.
      </p>
    </>
  );
}

