// Money never leaves integer arithmetic: dividing minor units by 100 to hand a
// float to Intl would put the money path on binary fractions for the sake of
// display. The whole and fractional parts are split with integer ops instead.
export function formatMinor(amountMinor: number): string {
  const negative = amountMinor < 0;
  const absolute = Math.abs(amountMinor);
  const dollars = countFormatter.format(Math.trunc(absolute / 100));
  const cents = String(absolute % 100).padStart(2, "0");

  return `${negative ? "-" : ""}$${dollars}.${cents}`;
}

